+@page "/dashboard"
+@rendermode InteractiveServer
+@inject WarehouseState Warehouse
+@inject InventoryAlertService AlertService
+@implements IDisposable
+
+<PageTitle>Dashboard</PageTitle>
+
+<h1>Warehouse Dashboard</h1>
+
+<div class="card mt-3" style="max-width: 400px;">
+    <div class="card-body">
+        <h5 class="card-title">
+            Low-Stock Alerts
+            @if (AlertService.LastLowStockCount > 0)
+            {
+                <span class="badge bg-danger ms-2">@AlertService.LastLowStockCount</span>
+            }
+            else
+            {
+                <span class="badge bg-success ms-2">0</span>
+            }
+        </h5>
+        <p class="card-text text-muted">
+            Monitoring <strong>@CurrentWarehouseName</strong> — refreshes every 10 seconds.
+        </p>
+    </div>
+</div>
+
+@code {
+    private PeriodicTimer? _timer;
+    private CancellationTokenSource? _cts;
+
+    private string CurrentWarehouseName =>
+        WarehouseState.AvailableWarehouses
+            .FirstOrDefault(w => w.Id == Warehouse.CurrentWarehouseId)?.Name
+        ?? "Unknown";
+
+    private Action? _warehouseHandler;
+    private Action? _alertHandler;
+
+    protected override void OnInitialized()
+    {
+        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
+        Warehouse.OnChange += _warehouseHandler;
+
+        _alertHandler = () => InvokeAsync(StateHasChanged);
+        AlertService.OnAlertCountChanged += _alertHandler;
+    }
+
+    protected override void OnAfterRender(bool firstRender)
+    {
+        if (firstRender)
+        {
+            StartPolling();
+        }
+    }
+
+    private void StartPolling()
+    {
+        StopPolling();
+        _cts = new CancellationTokenSource();
+        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
+        _ = PollLoopAsync(_cts.Token);
+    }
+
+    private async Task PollLoopAsync(CancellationToken ct)
+    {
+        // Fetch immediately on start.
+        await FetchAlerts();
+
+        try
+        {
+            while (await _timer!.WaitForNextTickAsync(ct))
+            {
+                await FetchAlerts();
+            }
+        }
+        catch (OperationCanceledException) { }
+    }
+
+    private async Task FetchAlerts()
+    {
+        var count = await AlertService.GetLowStockCountAsync(Warehouse.CurrentWarehouseId);
+        // Notify ALL subscribers (sidebar badge + this page).
+        AlertService.UpdateCount(count);
+    }
+
+    private async Task OnWarehouseChanged()
+    {
+        // Warehouse changed — restart polling for new warehouse and fetch immediately.
+        StartPolling();
+        StateHasChanged();
+    }
+
+    private void StopPolling()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+        _cts = null;
+        _timer?.Dispose();
+        _timer = null;
+    }
+
+    public void Dispose()
+    {
+        StopPolling();
+        Warehouse.OnChange -= _warehouseHandler;
+        AlertService.OnAlertCountChanged -= _alertHandler;
+    }
+}
+

